"""ReportLab paragraph fitting for OCR source rectangles."""

from dataclasses import dataclass
from typing import Any, Literal, cast
from xml.sax.saxutils import escape


Alignment = Literal["left", "center", "right", "justify"]


@dataclass(frozen=True)
class PatchTextOptions:
    """Typography and failure policy for text replacing an OCR bounding box."""

    font_name: str = "STSong-Light"
    max_font_size: float = 12.0
    min_font_size: float = 4.0
    line_height: float = 1.2
    horizontal_padding: float = 1.0
    vertical_padding: float = 1.0
    alignment: Alignment = "left"
    overflow: Literal["error", "skip"] = "error"


@dataclass(frozen=True)
class FittedParagraph:
    """A paragraph proven to fit within a particular rectangle."""

    paragraph: Any
    font_size: float
    width: float
    height: float


class BoxTextLayout:
    """Fit continuous text into a fixed ReportLab rectangle without truncation."""

    def __init__(self, options: PatchTextOptions | None = None) -> None:
        self.options = options or PatchTextOptions()
        self._validate_options()

    def fit(self, text: str, width: float, height: float) -> FittedParagraph:
        """Return the largest quarter-point Paragraph that completely fits."""
        normalized = " ".join(text.split())
        if not normalized:
            raise ValueError("replacement text must not be empty")
        available_width = width - (2 * self.options.horizontal_padding)
        available_height = height - (2 * self.options.vertical_padding)
        if available_width <= 0 or available_height <= 0:
            raise ValueError("bbox is too small after text padding")

        self._ensure_font(normalized)
        minimum = self._paragraph(normalized, self.options.min_font_size)
        minimum_width, minimum_height = self._natural_size(minimum, available_width)
        if minimum_width > available_width or minimum_height > available_height:
            raise ValueError(
                "replacement text cannot fit bbox at minimum font size "
                f"{self.options.min_font_size}: required {minimum_width:.2f}x{minimum_height:.2f}, "
                f"available {available_width:.2f}x{available_height:.2f}"
            )

        low = int(round(self.options.min_font_size * 4))
        high = int(round(self.options.max_font_size * 4))
        best: FittedParagraph | None = None
        while low <= high:
            middle = (low + high) // 2
            font_size = middle / 4
            paragraph = self._paragraph(normalized, font_size)
            natural_width, natural_height = self._natural_size(paragraph, available_width)
            if natural_width <= available_width and natural_height <= available_height:
                best = FittedParagraph(paragraph, font_size, natural_width, natural_height)
                low = middle + 1
            else:
                high = middle - 1
        if best is None:  # Defensive: min size was already checked above.
            raise ValueError("replacement text cannot fit bbox")
        return best

    def _paragraph(self, text: str, font_size: float):
        from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT, TA_RIGHT
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.platypus import Paragraph

        alignment = {
            "left": TA_LEFT,
            "center": TA_CENTER,
            "right": TA_RIGHT,
            "justify": TA_JUSTIFY,
        }[self.options.alignment]
        style = ParagraphStyle(
            "pdf-craft-patch",
            fontName=self.options.font_name,
            fontSize=font_size,
            leading=font_size * self.options.line_height,
            alignment=cast(Any, alignment),
            wordWrap="CJK",
        )
        return Paragraph(escape(text), style)

    @staticmethod
    def _natural_size(paragraph, width: float) -> tuple[float, float]:
        # A very tall frame asks Platypus for the full natural height rather
        # than allowing a too-short frame to split and hide trailing content.
        return paragraph.wrap(width, 1_000_000)

    def _ensure_font(self, text: str) -> None:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.cidfonts import UnicodeCIDFont

        if self.options.font_name == "STSong-Light":
            try:
                pdfmetrics.getFont(self.options.font_name)
            except KeyError:
                pdfmetrics.registerFont(UnicodeCIDFont(self.options.font_name))
        try:
            pdfmetrics.getFont(self.options.font_name)
        except KeyError as error:
            raise ValueError(f"PDF patch font is unavailable: {self.options.font_name}") from error
        if any(ord(character) > 255 for character in text) and self.options.font_name in {
            "Courier", "Courier-Bold", "Courier-Oblique", "Courier-BoldOblique",
            "Helvetica", "Helvetica-Bold", "Helvetica-Oblique", "Helvetica-BoldOblique",
            "Times-Roman", "Times-Bold", "Times-Italic", "Times-BoldItalic",
        }:
            raise ValueError(
                f"font {self.options.font_name} cannot reliably draw non-Latin replacement text"
            )

    def _validate_options(self) -> None:
        options = self.options
        if options.min_font_size <= 0 or options.max_font_size < options.min_font_size:
            raise ValueError("font sizes must be positive and max_font_size >= min_font_size")
        if options.line_height <= 0:
            raise ValueError("line_height must be positive")
        if options.horizontal_padding < 0 or options.vertical_padding < 0:
            raise ValueError("text padding must not be negative")
        if options.alignment not in {"left", "center", "right", "justify"}:
            raise ValueError(f"unsupported text alignment: {options.alignment}")
        if options.overflow not in {"error", "skip"}:
            raise ValueError(f"unsupported overflow policy: {options.overflow}")

from collections.abc import Callable
from pathlib import Path

from pdf_craft.extractor.chapter.chapter import Chapter, ParagraphLayout
from pdf_craft.extractor.chapter.chapter import InlineExpression, Reference
from pdf_craft.extractor.chapter.reader import create_chapters_reader
from pdf_craft.markdown.paragraph import HTMLTag
from pdf_craft.expression import to_markdown_string
from pdf_craft.document import DocumentPackage
from pdf_craft.pdf.handler import PDFHandler
from pdf_craft.pipeline.pdf.patcher import PDFPatcher, PDFReplacement
from pdf_craft.transformer import ChapterTransformer


class PDFTranslationPipeline:
    """Apply a replace-only text transformer to an extracted PDF package."""

    def __init__(self, pdf_handler: PDFHandler | None = None, patcher: PDFPatcher | None = None, dpi: int = 300) -> None:
        self.pdf_handler = pdf_handler
        self.patcher = patcher or PDFPatcher(pdf_handler=pdf_handler)
        self.dpi = dpi

    def translate(
        self,
        pdf_path: Path,
        target_path: Path,
        package: DocumentPackage | Path,
        transformer: Callable[[str], str] | ChapterTransformer,
    ) -> None:
        package = package if isinstance(package, DocumentPackage) else DocumentPackage.from_path(package)
        package.validate()
        document = self.pdf_handler.open(pdf_path) if self.pdf_handler else None
        replacements: list[PDFReplacement] = []
        try:
            pages = package.page_pixel_sizes()
            reader = create_chapters_reader(package.chapters_path)
            for chapter in reader():
                structured = not callable(transformer)
                transformed = transformer.transform(chapter) if structured else chapter
                callback = transformer if callable(transformer) else (lambda text: text)
                self._collect_chapter(transformed, callback, document, pages, replacements, structured)
        finally:
            if document:
                document.close()
        self.patcher.patch(pdf_path, target_path, replacements)

    def patch(
        self,
        pdf_path: Path,
        target_path: Path,
        package: DocumentPackage | Path,
    ) -> None:
        """Write the text already present in ``package`` back to ``pdf_path``.

        This is deliberately separate from :meth:`translate`: the package is
        already the source of the replacement text, so no OCR or LLM
        transformer is involved.
        """
        package = package if isinstance(package, DocumentPackage) else DocumentPackage.from_path(package)
        package.validate()
        document = self.pdf_handler.open(pdf_path) if self.pdf_handler else None
        replacements: list[PDFReplacement] = []
        try:
            pages = package.page_pixel_sizes()
            reader = create_chapters_reader(package.chapters_path)
            for chapter in reader():
                self._collect_chapter(
                    chapter, lambda text: text, document, pages, replacements, structured=True,
                )
        finally:
            if document:
                document.close()
        self.patcher.patch(pdf_path, target_path, replacements)

    def _collect_chapter(self, chapter: Chapter, transformer, document, pages, replacements, structured: bool = False) -> None:
        for layout in chapter.layouts:
            if not isinstance(layout, ParagraphLayout) or layout.ref not in {"text", "sub_title"}:
                continue
            for block in layout.blocks:
                source = _to_patch_text(block.content).strip()
                if not source:
                    continue
                translated = transformer(source)
                if not translated or (translated == source and not structured):
                    continue
                if block.page_index not in pages:
                    if document is None:
                        raise ValueError("PDF handler is required to resolve page dimensions")
                    image = document.render_page(block.page_index, self.dpi)
                    pages[block.page_index] = image.size
                replacements.append(PDFReplacement(
                    block.page_index, block.det, translated, pages[block.page_index], self.dpi,
                    reading_order=block.order,
                ))


def _to_patch_text(items) -> str:
    """Serialize structured Chapter content without silently dropping nodes.

    The patcher can only draw text, so formulas retain their Markdown delimiters,
    references retain their printed mark, and HTML wrappers retain their children.
    """
    parts: list[str] = []
    for item in items:
        if isinstance(item, str):
            parts.append(item)
        elif isinstance(item, InlineExpression):
            parts.append(to_markdown_string(item.kind, item.content))
        elif isinstance(item, Reference):
            parts.append(str(item.mark))
        elif isinstance(item, HTMLTag):
            parts.append(_to_patch_text(item.children))
        else:
            raise TypeError(f"unsupported chapter content for PDF patching: {type(item).__name__}")
    return "".join(parts)
